/**
 * Pixel art as row strings, one character per art pixel, `.` = empty. Same idea as the nav icons
 * in the shell, drawn on a larger grid. Every character maps to a palette tone in bundle.css
 * (`.bb-px-<char>` for icons, `.bb-sky-<char>` for the skyline), so the art follows the theme and
 * nothing here carries a colour value.
 *
 * Game icons live in icon-art.ts (generated by tools/pixel-art/icons/build.js).
 *
 * Skyline (96 by 14):
 *   s star   m moon or sun   f far buildings   n near buildings   v lit window
 */

export { GAME_ICON_NAMES, GAME_ICON_ROWS, ICON_LEGEND } from './icon-art.ts';
export type { GameIconName } from './icon-art.ts';

